def is_anagram(s, t):
    return sorted(s) == sorted(t)

def substrings(s):
    for i in range(len(s)):
        for j in range(i+1, len(s)+1):
            yield s[i:j]

def f(s):
    cnt, M = 0, {}
    for i in substrings(s):
        h = hash(sorted(i))
        if h not in M:
            M[h] = len(i)
        else:
            cnt += M[h]
    return cnt

def solve(n, strings):
    return " ".join([str(f(x)) for x in strings])

def main():
    n = int(input())
    strings = []
    for i in range(n):
        strings.append(input())
    print(solve(n, strings))

