def collect_rotations(arr):
    groups = {}
    for item in arr:
        p = permutations(item.lower())
        for perm in p:
            perm_str = ''.join(perm)
            if perm_str in groups:
                groups[perm_str].append(item)
            else:
                groups[perm_str] = [item]
    sorted_groups = []
    for group in groups.values():
        group.sort()
        sorted_groups.append(group)
    sorted_groups.sort(key=lambda x: (len(x), x[0].upper()))
    return sorted_groups
